 *   - 用户可手动触发分析（命令面板）
 *   - 所有功能可独立开关
 * ============================================================
 */

import * as vscode from 'vscode';
import { loadConfig, onConfigChange } from './config';
import { analyzeContent, AnalysisResult } from './bridgeClient';
import { getCachedResult, setCachedResult } from './cache';
import { registerSemanticTokenProvider, updateSemanticResult, clearSemanticResult, fireSemanticTokensChanged } from './semanticTokens';
import { registerIndentDecorations, renderIndentLines, updateDecorationsFromAnalysis } from './indentDecoration';
import { registerHoverFeature, updateEntities } from './hoverFeature';
import { registerDiagnosticManager, updateDiagnostics, getDiagnosticStats } from './diagnosticManager';
import { registerSessionManager, recordAnalysis, getSessionSummary, activateSession } from './sessionManager';

/**
 * 防抖定时器
 */
let debounceTimer: ReturnType<typeof setTimeout> | undefined;

/**
 * 进行中的分析请求对应的文档版本号
 * 用于丢弃过期请求的响应（修复 Bug 6 竞态条件）
 */
let pendingAnalysisVersion = 0;

/**
 * 状态栏项（显示分析状态）
 */
let statusBarItem: vscode.StatusBarItem;

/**
 * 桥接服务连接状态
 */
let bridgeConnected = false;

/**
 * 插件激活入口
 * 当 VS Code 打开 .mind 文件时自动调用
 *
 * @param context - 扩展上下文（用于注册资源和清理）
 */
export function activate(context: vscode.ExtensionContext): void {
  console.log('[Mind] 插件激活中...');

  // ---- 1. 创建状态栏 ----
  statusBarItem = vscode.window.createStatusBarItem(
    vscode.StatusBarAlignment.Left,
    100
  );
  statusBarItem.text = '$(symbol-namespace) Mind';
  statusBarItem.tooltip = 'Mind 语义分析 — 点击查看状态';
  statusBarItem.command = 'mind.showStatus';
  statusBarItem.show();
  context.subscriptions.push(statusBarItem);

  // ---- 2. 注册语言功能 ----
  registerSemanticTokenProvider(context);
  registerIndentDecorations(context);
  registerHoverFeature(context);
  registerDiagnosticManager(context);
  registerSessionManager(context);

  // ---- 3. 注册命令 ----
  registerCommands(context);

  // ---- 4. 检查桥接服务连接 ----
  checkBridgeConnection();

  // ---- 5. 如果当前已有打开的 .mind 文件，立即分析 ----
  const editor = vscode.window.activeTextEditor;
  if (editor && editor.document.languageId === 'mind') {
    triggerAnalysis(editor.document);
  }

  // ---- 6. 监听文件内容变化（防抖触发分析） ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeTextDocument((event) => {
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document === event.document && editor.document.languageId === 'mind') {
        // 清除之前的定时器
        if (debounceTimer) {
          clearTimeout(debounceTimer);
        }

        // 设置新的防抖定时器
        const config = loadConfig();
        debounceTimer = setTimeout(() => {
          triggerAnalysis(editor.document);
        }, config.analysisDebounce);
      }
    })
  );

  // ---- 7. 监听编辑器切换（切换文件时自动分析） ----
  context.subscriptions.push(
    vscode.window.onDidChangeActiveTextEditor((editor) => {
      if (editor && editor.document.languageId === 'mind') {
        // 切换激活会话
        activateSession(editor.document.uri.fsPath);

        // 检查缓存，如果没有缓存则触发分析
        const content = editor.document.getText();
        const cached = getCachedResult(editor.document.uri.toString(), content);
        if (!cached) {
          triggerAnalysis(editor.document);
        } else {
          // 有缓存，直接使用
          applyAnalysisResult(editor.document, cached);
        }
      }
    })
  );

  // ---- 8. 监听配置变化 ----
  context.subscriptions.push(
    onConfigChange((config) => {
      // 防抖时间变化不影响正在等待的定时器
      // 桥接服务地址变化时重新连接
      checkBridgeConnection();
    })
  );

  console.log('[Mind] 插件激活完成');
}

/**
 * 注册所有命令
 */
function registerCommands(context: vscode.ExtensionContext): void {
  // ---- 立即分析命令 ----
  context.subscriptions.push(
    vscode.commands.registerCommand('mind.analyzeNow', () => {
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document.languageId === 'mind') {
        statusBarItem.text = '$(sync~spin) Mind 分析中...';
        triggerAnalysis(editor.document);
      } else {
        vscode.window.showInformationMessage('请打开一个 .mind 文件');
      }
    })
  );

  // ---- 重新连接桥接服务命令 ----
  context.subscriptions.push(
    vscode.commands.registerCommand('mind.restartBridge', () => {
      checkBridgeConnection();
      // 重新分析当前文件
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document.languageId === 'mind') {
        triggerAnalysis(editor.document);
      }
    })
  );

  // ---- 显示分析状态命令 ----
  context.subscriptions.push(
    vscode.commands.registerCommand('mind.showStatus', () => {
      const editor = vscode.window.activeTextEditor;
      const filePath = editor?.document?.uri?.fsPath || '无';
      const sessionInfo = getSessionSummary(filePath);

      const stats = editor
        ? getDiagnosticStats(editor.document.uri)
        : { errors: 0, warnings: 0 };

      vscode.window.showInformationMessage(
        `Mind 分析状态\n` +
        `桥接服务: ${bridgeConnected ? '✅ 已连接' : '❌ 未连接'}\n` +
        `文件: ${filePath}\n` +
        `${sessionInfo}\n` +
        `诊断: ${stats.errors} 错误, ${stats.warnings} 警告`,
        { modal: true }
      );
    })
  );
}

/**
 * 检查桥接服务连接状态
 */
async function checkBridgeConnection(): Promise<void> {
  const config = loadConfig();
  try {
    const response = await fetch(`http://${config.bridgeHost}:${config.bridgePort}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    bridgeConnected = response.ok;

    if (bridgeConnected) {
      statusBarItem.text = '$(symbol-namespace) Mind';
      statusBarItem.tooltip = '桥接服务已连接';
      console.log('[Mind] 桥接服务连接成功');
    } else {
      statusBarItem.text = '$(warning) Mind';
      statusBarItem.tooltip = '桥接服务异常';
      bridgeConnected = false;
    }
  } catch {
    bridgeConnected = false;
    statusBarItem.text = '$(warning) Mind (离线)';
    statusBarItem.tooltip = '桥接服务未连接 — 仅显示基本语法高亮';
    console.warn('[Mind] 桥接服务未连接，将使用离线模式');
  }
}

/**
 * 触发文件分析
 *
 * 工作流:
 *   1. 检查缓存
 *   2. 发送到桥接服务
 *   3. 更新所有渲染
 *
 * @param document - 要分析的文档
 */
async function triggerAnalysis(document: vscode.TextDocument): Promise<void> {
  if (!document || document.languageId !== 'mind') return;

  const filePath = document.uri.toString();
  const content = document.getText();

  // 空文件不分析
  if (!content.trim()) {
    updateDiagnostics(document.uri, []);
    return;
  }

  // ---- 1. 检查本地缓存 ----
  const cached = getCachedResult(filePath, content);
  if (cached) {
    updateSemanticResult(filePath, cached);
    fireSemanticTokensChanged();
    applyAnalysisResult(document, cached);
    return;
  }

  // ---- 2. 记录当前请求的版本号（用于去重） ----
  pendingAnalysisVersion++;
  const thisVersion = pendingAnalysisVersion;
  const config = loadConfig();
  statusBarItem.text = '$(sync~spin) Mind 分析中...';

  const result = await analyzeContent(content, config.bridgeHost, config.bridgePort);

  // ---- 如果版本号变了，说明有更新请求已发出，丢弃本次结果 ----
  if (thisVersion !== pendingAnalysisVersion) {
    console.log('[Mind] 丢弃过期分析结果（版本', thisVersion, '→', pendingAnalysisVersion, '）');
    return;
  }

  if (result) {
    // ---- 3. 缓存并应用结果 ----
    setCachedResult(filePath, content, result);
    updateSemanticResult(filePath, result);
    recordAnalysis(filePath);
    applyAnalysisResult(document, result);
    // 通知 VS Code 刷新语义令牌着色
    fireSemanticTokensChanged();

    // 更新状态栏
    const stats = getDiagnosticStats(document.uri);
    statusBarItem.text = `$(symbol-namespace) Mind ${stats.errors > 0 ? '$(error)' : '$(check)'}`;
    statusBarItem.tooltip = `错误: ${stats.errors}, 警告: ${stats.warnings}`;
  } else {
    // 桥接服务不可用，显示提示
    statusBarItem.text = '$(warning) Mind (离线)';
    statusBarItem.tooltip = '桥接服务不可用，仅显示基本语法高亮';

    // 不清除诊断，保留之前的分析结果
    console.warn('[Mind] 分析请求失败，使用缓存或降级模式');
  }
}

/**
 * 将分析结果应用到编辑器
 * 更新所有视觉元素：颜色/缩进线/悬停/诊断
 *
 * @param document - 目标文档
 * @param result - 分析结果
 */
function applyAnalysisResult(document: vscode.TextDocument, result: AnalysisResult): void {
  const editor = vscode.window.activeTextEditor;
  if (!editor || editor.document !== document) return;

  // ---- 更新缩进关系线 ----
  if (result.nesting && result.nesting.length > 0) {
    updateDecorationsFromAnalysis(editor, result.nesting);
  } else {
    renderIndentLines(editor);
  }

  // ---- 更新悬停实体数据 ----
  if (result.entities) {
    updateEntities(document.uri.toString(), result.entities);
  }

  // ---- 更新诊断（红/绿波浪线） ----
  if (result.diagnostics) {
    updateDiagnostics(document.uri, result.diagnostics);
  } else {
    updateDiagnostics(document.uri, []);
  }

  // 语义令牌提供器直接读取全局的 lastAnalysisResults
  // VS Code 会在编辑时自动重新请求语义令牌
}

/**
 * 插件停用入口
 */
export function deactivate(): void {
  console.log('[Mind] 插件停用');

  // 清除防抖定时器
  if (debounceTimer) {
    clearTimeout(debounceTimer);
    debounceTimer = undefined;
  }

  // 清理状态
  bridgeConnected = false;
}

/**
 * ============================================================
 * Mind 插件 — 缩进关系线装饰
 * ============================================================
 * 在文本左侧绘制彩色垂直缩进线，表示逻辑从属关系。
 *
 * 效果:
 *   │ Count node num
 *   │ if num ≥ 30
 *   │   ├─ delete minimum num
 *   │   └─ add node count to total
 *   │ print result
 *
 * 设计:
 *   - 每层缩进对应一根垂直线
 *   - 每层线的颜色不同（从 indentColors 数组中按索引取色）
 *   - 用户可在设置中开关和自定义颜色
 *   - 每当编辑器内容变化或分析结果更新时重新渲染
 * ============================================================
 */

import * as vscode from 'vscode';
import { AnalysisResult, NestingInfo } from './bridgeClient';
import { loadConfig, MindConfig } from './config';

/** 装饰类型集合（每种层级一个） */
let indentDecorations: vscode.TextEditorDecorationType[] = [];

/**
 * 注册缩进关系线
 * 监听编辑器事件，在有 .mind 文件打开时渲染缩进线
 *
 * @param context - 扩展上下文
 */
export function registerIndentDecorations(context: vscode.ExtensionContext): void {
  const config = loadConfig();

  // ---- 初始化装饰类型 ----
  rebuildDecorationTypes(config);

  // ---- 监听活跃编辑器变化 ----
  context.subscriptions.push(
    vscode.window.onDidChangeActiveTextEditor((editor) => {
      if (editor && editor.document.languageId === 'mind') {
        updateDecorations(editor);
      }
    })
  );

  // ---- 监听文本内容变化 ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeTextDocument((event) => {
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document === event.document && editor.document.languageId === 'mind') {
        // 缩进线由文本缩进直接决定，不依赖 AI 分析
        renderIndentLines(editor);
      }
    })
  );

  // ---- 监听配置变化（实时更新颜色） ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeConfiguration((event) => {
      if (event.affectsConfiguration('mind.indentColors') || event.affectsConfiguration('mind.enableIndentLines')) {
        const newConfig = loadConfig();
        rebuildDecorationTypes(newConfig);

        const editor = vscode.window.activeTextEditor;
        if (editor && editor.document.languageId === 'mind') {
          renderIndentLines(editor);
        }
      }
    })
  );

  // ---- 初始渲染 ----
  if (vscode.window.activeTextEditor?.document.languageId === 'mind') {
    renderIndentLines(vscode.window.activeTextEditor);
  }
}

/**
 * 重建所有层级的装饰类型
 * 在颜色配置变化时调用
 */
function rebuildDecorationTypes(config: MindConfig): void {
  // 清除旧装饰
  for (const dec of indentDecorations) {
    dec.dispose();
  }
  indentDecorations = [];

  // 如果缩进线被禁用，不创建装饰
  if (!config.enableIndentLines) return;

  // 为每个层级创建装饰类型
  // 最多支持 8 层缩进
  const maxLevels = Math.min(config.indentColors.length, 8);
  for (let level = 0; level < maxLevels; level++) {
    const color = config.indentColors[level] || config.indentColors[config.indentColors.length - 1];

    indentDecorations.push(
      vscode.window.createTextEditorDecorationType({
        before: {
          contentText: '│ ',
          color: color,
          fontWeight: 'normal',
          margin: '0 0 0 0',
        },
        opacity: '0.6',
        rangeBehavior: vscode.DecorationRangeBehavior.OpenOpen,
      })
    );
  }
}

/**
 * 渲染缩进关系线
 * 基于每行开头的缩进空格数绘制层级竖线
 *
 * @param editor - 当前编辑器
 */
export function renderIndentLines(editor: vscode.TextEditor): void {
  const config = loadConfig();
  if (!config.enableIndentLines) {
    // 清除所有缩进线
    for (const dec of indentDecorations) {
      editor.setDecorations(dec, []);
    }
    return;
  }

  const document = editor.document;
  const lineCount = document.lineCount;

  // 为每层收集需要添加装饰的行
  const linesPerLevel: Map<number, vscode.Range[]> = new Map();
  for (let level = 0; level < indentDecorations.length; level++) {
    linesPerLevel.set(level, []);
  }

  for (let lineIdx = 0; lineIdx < lineCount; lineIdx++) {
    const line = document.lineAt(lineIdx);

    // 跳过空行
    if (line.isEmptyOrWhitespace) continue;

    // 计算缩进层级（每 2 个空格 = 1 级）
    const indentText = line.text.match(/^(\s*)/)?.[1] || '';
    const level = Math.floor(indentText.length / 2);

    // 为当前层级及以上的所有层级添加竖线
    // 即：如果 level=2，画 3 根线（level 0, 1, 2）
    for (let l = 0; l <= level && l < indentDecorations.length; l++) {
      const ranges = linesPerLevel.get(l);
      if (ranges) {
        ranges.push(new vscode.Range(lineIdx, 0, lineIdx, 0));
      }
    }
  }

  // 应用装饰
  for (let level = 0; level < indentDecorations.length; level++) {
    const ranges = linesPerLevel.get(level) || [];
    const decoration = indentDecorations[level];
    if (decoration) {
      editor.setDecorations(decoration, ranges);
    }
  }
}

/**
 * 根据 AI 分析的 nesting 数据更新缩进线
 * 当 AI 分析结果返回时调用，使用 AI 的层级判断（更准确）
 *
 * @param editor - 当前编辑器
 * @param nesting - AI 分析的缩进层级数据
 */
export function updateDecorationsFromAnalysis(
  editor: vscode.TextEditor,
  nesting: NestingInfo[]
): void {
  const config = loadConfig();
  if (!config.enableIndentLines) return;

  // 如果 AI 提供了 nesting 数据，使用它；否则回退到本地缩进计算
  if (nesting && nesting.length > 0) {
    const linesPerLevel: Map<number, vscode.Range[]> = new Map();
    for (let level = 0; level < indentDecorations.length; level++) {
      linesPerLevel.set(level, []);
    }

    for (const n of nesting) {
      const level = n.level;
      for (let l = 0; l <= level && l < indentDecorations.length; l++) {
        const ranges = linesPerLevel.get(l);
        if (ranges) {
          ranges.push(new vscode.Range(n.line, 0, n.line, 0));
        }
      }
    }

    for (let level = 0; level < indentDecorations.length; level++) {
      const ranges = linesPerLevel.get(level) || [];
      const decoration = indentDecorations[level];
      if (decoration) {
        editor.setDecorations(decoration, ranges);
      }
    }
  } else {
    renderIndentLines(editor);
  }
}

/**
 * 更新装饰（从分析结果或本地计算）
 */
function updateDecorations(editor: vscode.TextEditor): void {
  renderIndentLines(editor);
}

