const resultsMap = new Map<string, AnalysisResult>();

/**
 * 更新语义令牌数据（由 extension.ts 在分析完成后调用）
 */
export function updateSemanticResult(uri: string, result: AnalysisResult): void {
  resultsMap.set(uri, result);
}

/**
