  'nlVerb',        // 12: 自然语言动词
  'nlNoun',        // 13: 自然语言名词
  'builtin',       // 14: 内置函数/关键字
  'entity',        // 15: 实体名
  'arrow',         // 16: 指针/箭头
  'macro',         // 17: 特殊常量
];

